        let manager = AdvancedCacheManager::new(config)
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;

        manager
            .put("key1", "bvalue1".to_vec())
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;
        manager
            .put("key2", "bvalue2".to_vec())
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;
        manager
            .put("key3", "bvalue3".to_vec())
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;

        let result = manager
            .get("key1")
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?;
        assert_eq!(result, None);

        assert!(manager
            .get("key2")
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?
            .is_some());
        assert!(manager
            .get("key3")
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?
