            .get("key1")
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?; // Hit
        let _ = manager
            .get("key2")
            .map_err(|e| BearDogError::system(format!("Error: {:?}", e)))?; // Miss

        let metrics = manager.get_metrics();
        assert!(metrics.hits > 0);
        assert!(metrics.misses > 0);
        assert!(metrics.hit_rate() > 0.0);
    }

