        if let Ok(Ok(_)) = tokio::time::timeout(Duration::from_secs(1), hog).await {
            hog_results += 1;
        }
    }

    // Wait for normal operations
    for op in normal_ops {
        if let Ok(Ok(_)) = tokio::time::timeout(Duration::from_secs(2), op).await {
            normal_results += 1;
        }
    }

