            $expected,
            Some(
                $crate::tests::common::assertions::AssertionContext::new("assert_err_contains")
                    .with_location(file!(), line!()),
            ),
        )?;
    };
    ($result:expr, $expected:expr, $context:expr) => {
        $crate::tests::common::assertions::assert_error_contains(
            &$result,
            $expected,
            Some($context),
        )?;
    };
}

