        let pool = ZeroCopyBufferPool::new()
            .map_err(|e| BearDogError::system({:?}", e)))?;
        let start = Instant::now();

        let mut buffers = Vec::new();
        for _ in 0..1000 {
            let buffer = pool
                .get_buffer(4096)
                .map_err(|e| BearDogError::system({:?}", e)))?;
            buffers.push(buffer);
        }

        let allocation_time = start.elapsed();
        assert!(
            allocation_time < Duration::from_millis({:?}",
