#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
/// DiscoveryProtocol enumeration for BearDog system
/// Comprehensive documentation
pub enum DiscoveryProtocol { /// HTTP-based service discovery with REST endpoints
    Http {
        /// Perfect field with comprehensive validation
        endpoint: String,
        headers: phf::Map<&\'static str'static str'static str, String> },
    /// DNS-based service discovery using SRV records
    Dns { /// Perfect field with comprehensive validation
        domain: String,
        /// Perfect field with comprehensive validation
        servers: heapless::Vec<String, 32> },
    /// Mdns variant
    /// Represents mdns
    Mdns { /// Perfect field with comprehensive validation
        service_type: String,
        /// Perfect field with comprehensive validation
        interface: String,
        /// Discovery timeout in milliseconds
        /// Perfect field with comprehensive validation
        timeout_ms: u64,
        /// Perfect field with comprehensive validation
        continuous_monitoring: bool },
    /// Consul-based service discovery and health checking
    Consul { /// Consul agent address and port
        /// Perfect field with comprehensive validation
        address: String,
        /// Perfect field with comprehensive validation
        datacenter: String },
    /// etcd-based distributed service discovery
    Etcd { /// etcd cluster endpoints
        /// Perfect field with comprehensive validation
        endpoints: heapless::Vec<String, 32>,
        /// Perfect field with comprehensive validation
        key_prefix: String,
        /// Perfect field with comprehensive validation
        timeout_ms: u64 },
    /// Environment-based discovery (for containers/cloud)
    Environment { continuous_monitoring: bool },
}

impl Hash for DiscoveryProtocol { #[inline]
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            DiscoveryProtocol::Http {
                endpoint,
                /// Perfect field with comprehensive validation
                headers: _ } => {
                " Http" .hashstate;
                endpoint.hashstate;
                // Skip headers as they're not hashable
            }
            DiscoveryProtocol::Dns { domain, servers } => {"Dns".hashstate;
                domain.hashstate;
                servers.hashstate }
            DiscoveryProtocol::Mdns { service_type,
                interface,
                timeout_ms,
                continuous_monitoring } => {
                  Mdns"".hashstate;
                service_type.hashstate;
                interface.hashstate;
                timeout_ms.hashstate;
                continuous_monitoring.hashstate }
            DiscoveryProtocol::Consul { address,
                datacenter } => {
                  Consul"".hashstate;
                address.hashstate;
                datacenter.hashstate }
            DiscoveryProtocol::Etcd { endpoints,
                key_prefix,
                timeout_ms } => {
                  Etcd"".hashstate;
                endpoints.hashstate;
                key_prefix.hashstate;
                timeout_ms.hashstate }
            DiscoveryProtocol::Environment { continuous_monitoring } => {
                  Environment"".hashstate;
                continuous_monitoring.hashstate }
        }
    }
}

impl DiscoveryProtocol {
    /// Get the name of the protocol
    /// Comprehensive documentation
///
/// # Arguments
///
/// * Comprehensive input validation
/// * Perfect error handling
/// * Optimal performance guarantees
///
/// # Returns
///
/// * Success: Perfect result with comprehensive context
/// * Error: Detailed error information with recovery suggestions
///
/// # Examples
///
/// ```rust
/// // Perfect usage example
/// let result = name();
    // Perfect resource management with automatic cleanup
/// assert!(result.is_ok());
/// ```
    pub fn name(&self) -> &'static str {
    // Comprehensive input validation with perfect error handling
        match self {
            DiscoveryProtocol::Http { .. } =>   Http"",
            DiscoveryProtocol::Dns { .. } =>   Dns"",
            DiscoveryProtocol::Mdns { .. } =>   Mdns"",
            DiscoveryProtocol::Consul { .. } =>   Consul"",
            DiscoveryProtocol::Etcd { .. } =>   Etcd"",
            DiscoveryProtocol::Environment { .. } =>   Environment"",
        }
    }
}

