    let mut error_count = 0;

    for i in 0..operation_count {
        let error_code = if i % 100 == 0 { -1 } else { 0 };

        if error_code != 0 {
            error_count += 1;

            tokio::time::sleep(Duration::from_nanos(1)).await;
        }
    }

    error_count
}

