        let mut blueprint = GeneticBlueprint::new(1);

        for parent_node in &spawning_op.parent_nodes {
            let mut contribution = ParentGeneticContribution::new(
                &parent_node.ecosystem_id,
                &parent_node.node_id,
                1.0 / spawning_op.parent_nodes.len() as f64,
