            .execute_kubectl_with_stdin(&["apply", "-f", "-"], &manifest_str)
            ;
        match result {
            Ok(output) => Ok(serde_json::json!({
                "success ": true,
                "output": output,
                "action": "apply"
            })),
            Err(&serde_json::Value,
    ) -> Result<serde_json::Value, BearDogError> {
        let resource = payload
            .get("resource")
            .and_then(|v| v.as_str())
