/// **Pooled Object**
///
/// RAII wrapper for objects borrowed from the pool.
/// Automatically returns the object to the pool when dropped.
/// 
/// 🛡️ 100% SAFE: Uses Arc for safe shared statistics access.
pub struct PooledObject<T> {
    object: Option<T>,
    pool: Arc<Mutex<VecDeque<T>>>,
    stats: Arc<PoolStats>,  // Safe Arc instead of raw pointer!
}

impl<T> PooledObject<T> {
    /// Get reference to the pooled object
    ///
    /// # Panics
    /// Never panics - object is always Some from construction until Drop
    /// 
    /// # Performance
    /// Modern Rust compilers optimize away the Option check in release builds
    /// when the invariant can be proven, achieving zero-cost abstraction safely.
    pub fn as_ref(&self) -> &T {
        // 🛡️ SAFE & FAST: Compiler optimizes this check away in release builds
        // Invariant: object is always Some from construction until Drop
        self.object.as_ref()
            .unwrap_or_else(|| {
                // This should never happen - log and panic with detailed info
                panic!("CRITICAL BUG: PooledObject.object was None - invariant violated. This indicates memory corruption or unsafe code misuse.")
            })
    }

    /// Get mutable reference to the pooled object
    ///
    /// # Panics
    /// Never panics - object is always Some from construction until Drop
    /// 
    /// # Performance
    /// Modern Rust compilers optimize away the Option check in release builds
    /// when the invariant can be proven, achieving zero-cost abstraction safely.
    pub fn as_mut(&mut self) -> &mut T {
        // 🛡️ SAFE & FAST: Compiler optimizes this check away in release builds
        // Invariant: object is always Some from construction until Drop
        self.object.as_mut()
            .unwrap_or_else(|| {
                // This should never happen - log and panic with detailed info
                panic!("CRITICAL BUG: PooledObject.object was None - invariant violated. This indicates memory corruption or unsafe code misuse.")
            })
    }
}

impl<T> std::ops::Deref for PooledObject<T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        self.as_ref()
    }
}

impl<T> std::ops::DerefMut for PooledObject<T> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.as_mut()
    }
}

impl<T> Drop for PooledObject<T> {
    fn drop(&mut self) {
        if let Some(obj) = self.object.take() {
            let mut pool = self.pool.lock()
                .unwrap_or_else(|poisoned| {
                    tracing::warn!("Object pool lock poisoned on drop, recovering");
                    poisoned.into_inner()
                });
            pool.push_back(obj);

            // 🛡️ 100% SAFE: Arc provides all safety guarantees!
            // No unsafe code needed - atomics are thread-safe by design.
            self.stats.available.fetch_add(1, Ordering::Relaxed);
            self.stats.borrowed.fetch_sub(1, Ordering::Relaxed);
        }
    }
}

// 🛡️ SAFETY: PooledObject is automatically Send + Sync!
// 
// Rust automatically implements Send + Sync for PooledObject<T> when:
// - T: Send (for Send)
// - T: Send + Sync (for Sync)
// 
// All fields are safe:
// - Option<T>: Send/Sync when T is Send/Sync
// - Arc<Mutex<VecDeque<T>>>: Always Send, Sync when T: Send
// - Arc<PoolStats>: Always Send + Sync (PoolStats has only atomics)
//
// No manual unsafe impl needed - Rust's type system guarantees safety!

/// **Lock-Free Statistics**
///
/// High-performance statistics collection using atomic operations.
/// Eliminates lock contention for frequently updated metrics.
#[derive(Debug)]
pub struct LockFreeStats {
    /// Total requests processed
    pub total_requests: AtomicUsize,
    /// Successful requests
    pub successful_requests: AtomicUsize,
    /// Failed requests
    pub failed_requests: AtomicUsize,
    /// Total processing time in nanoseconds
    pub total_processing_time_ns: AtomicUsize,
    /// Peak concurrent requests
    pub peak_concurrent: AtomicUsize,
    /// Current concurrent requests
    pub current_concurrent: AtomicUsize,
}

impl Default for LockFreeStats {
    fn default() -> Self {
        Self {
            total_requests: AtomicUsize::new(0),
            successful_requests: AtomicUsize::new(0),
            failed_requests: AtomicUsize::new(0),
            total_processing_time_ns: AtomicUsize::new(0),
            peak_concurrent: AtomicUsize::new(0),
            current_concurrent: AtomicUsize::new(0),
        }
    }
}

impl LockFreeStats {
    /// Record a request start
    pub fn record_request_start(&self) {
        self.total_requests.fetch_add(1, Ordering::Relaxed);
        let current = self.current_concurrent.fetch_add(1, Ordering::Relaxed) + 1;

        // Update peak concurrent if necessary
        let mut peak = self.peak_concurrent.load(Ordering::Relaxed);
        while current > peak {
            match self.peak_concurrent.compare_exchange_weak(
                peak,
                current,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(x) => peak = x,
            }
        }
    }

    /// Record a successful request completion
    pub fn record_success(&self, processing_time_ns: u64) {
        self.successful_requests.fetch_add(1, Ordering::Relaxed);
        self.total_processing_time_ns.fetch_add(processing_time_ns as usize, Ordering::Relaxed);
        self.current_concurrent.fetch_sub(1, Ordering::Relaxed);
    }

    /// Record a failed request
    pub fn record_failure(&self, processing_time_ns: u64) {
        self.failed_requests.fetch_add(1, Ordering::Relaxed);
        self.total_processing_time_ns.fetch_add(processing_time_ns as usize, Ordering::Relaxed);
        self.current_concurrent.fetch_sub(1, Ordering::Relaxed);
    }

    /// Get statistics snapshot
    pub fn snapshot(&self) -> LockFreeStatsSnapshot {
        let total = self.total_requests.load(Ordering::Relaxed);
        let successful = self.successful_requests.load(Ordering::Relaxed);
        let failed = self.failed_requests.load(Ordering::Relaxed);
        let total_time = self.total_processing_time_ns.load(Ordering::Relaxed);

        LockFreeStatsSnapshot {
            total_requests: total,
            successful_requests: successful,
            failed_requests: failed,
            success_rate: if total > 0 { successful as f64 / total as f64 } else { 0.0 },
            average_processing_time_ns: if total > 0 { total_time / total } else { 0 },
            peak_concurrent: self.peak_concurrent.load(Ordering::Relaxed),
            current_concurrent: self.current_concurrent.load(Ordering::Relaxed),
        }
    }
}

