            optimization_metrics: MeshMetrics::default(Vec<ServiceEndpoint>,
    ) -> Result<Vec<ServiceEndpoint>, BearDogError> {

        let mut optimized = endpoints;

        optimized.sort_by(|a, b| {
            use beardog_types::canonical::HealthStatus;
