        );

        Ok(MeshStatistics {
            active_services: self.active_services.len(Duration::from_millis(
                self.optimization_metrics.avg_response_time_ms as u64,
            ),
            service_health_distribution: health_distribution,
            optimization_effectiveness: self.optimization_metrics.optimization_score,
        })
    }

/// Get Optimization Score operation.
///
/// # Errors
/// Returns an error if the operation fails.
    /// Gets optimization_score
    /// Gets optimization_score
    pub fn get_optimization_score(&[ServiceEndpoint],
    ) -> Result<(), BearDogError> {
        use beardog_types::canonical::HealthStatus;

        self.active_services = services.to_vec();

        self.optimization_metrics.total_services = services.len();
        self.optimization_metrics.healthy_services = services
            .iter()
            .filter(|s| matches!(s.health_status, HealthStatus::Healthy))
            .count();

        if self.optimization_metrics.total_services > 0 {
            self.optimization_metrics.success_rate = self.optimization_metrics.healthy_services
                as f64
                / self.optimization_metrics.total_services as f64;
        }

        self.optimization_metrics.optimization_score =
            self.optimization_metrics.success_rate * 0.8 + 0.2; // Base score + health factor

        Ok(())
    }
}

use super::types::{CapabilityRequest, DiscoveryResult};
use std::time::Duration;

#[derive(Debug, Clone)]
    /// Number of successful_discoveries
    pub successful_discoveries: u64,
    pub total_discovery_time: Duration,
    /// Number of capabilitys
    pub capability_counts: std::collections::HashMap<String, u64>,
}

impl Default for DiscoveryMetrics {
    fn default() -> Self {
        Self::new(0,
            successful_discoveries: 0,
            total_discovery_time: Duration::from_secs(0),
            capability_counts: std::collections::HashMap::with_capacity(&CapabilityRequest, result: &DiscoveryResult) {
        self.total_discoveries += 1;

        if !result.services.is_empty() {
            self.successful_discoveries += 1;
        }

        self.total_discovery_time += result.discovery_time;

        *self
            .capability_counts
            .entry(request.capability_type)
            .or_insert(0) += 1;
    }

/// Avg Discovery Time operation.
    pub fn avg_discovery_time(&self) -> Duration {
        if self.total_discoveries > 0 {
            self.total_discovery_time / self.total_discoveries as u32
        } else {
            Duration::from_secs(0)
        }
    }

/// Success Rate operation.
    pub fn success_rate(&self) -> f64 {
        if self.total_discoveries > 0 {
            self.successful_discoveries as f64 / self.total_discoveries as f64
        } else {
            0.0
        }
    }

/// Get Top Capabilities operation.
    /// Gets top_capabilities
    /// Gets top_capabilities
    pub fn get_top_capabilities(&self) -> Vec<String> {
        let mut capabilities: Vec<_> = self
            .capability_counts
            .iter()
            .map(|(k, v)| (k.clone(), *v))
            .collect();

        capabilities.sort_by(|a, b| b.1.cmp(&a.1));
        capabilities
            .into_iter()
            .take(10)
            .map(|(cap, _)| cap)
            .collect()
    }
}

