    /// Optional ttl seconds
    pub ttl_seconds: Option<u64>,
    /// The freshness value
    pub freshness: f64,
}

impl CacheInfo {
    /// No Cache operation.
    #[must_use]
    pub const fn no_cache() -> Self {
        Self {
            cache_hit: false,
            cache_key: None,
            ttl_seconds: None,
            freshness: 1.0, // Fresh data
        }
    }

    /// Cache Hit operation.
    #[must_use]
    pub fn cache_hit(key: &str, ttl: u64, freshness: f64) -> Self {
        Self {
            cache_hit: true,
            cache_key: Some(key.to_string()),
            ttl_seconds: Some(ttl),
            freshness,
        }
    }
}

