            .rate_limiter
            .acquire()
            .await
            .map_err(|e| BearDogError::system(format!("Rate limit error: {e}")))?;

        debug!("Performing cached service discovery for: {}", service_type);
        Ok(vec![
            format!("service-{}-1", service_type),
            format!("service-{}-2", service_type),
        ])
    }

