    ExternalFunction, ExternalFunctionsRegistryConfig, FunctionHandle, FunctionMetadata,
    FunctionParameter, FunctionResult, FunctionSignature, FunctionValue, LibraryHandle,
    LibraryMetadata, LibraryStatus, SecurityClearance,
};
use beardog_errors::BearDogError;
use std::collections::HashMap;
use std::sync::Arc;
use tracing::info;
use uuid::Uuid;

/// External function registry
#[derive(Debug)]
pub struct ExternalFunctionRegistry {
    config: ExternalFunctionsRegistryConfig,
    libraries: HashMap<String, LibraryHandle>,
    functions: HashMap<String, FunctionHandle>,
    safety_checker: Arc<SafetyChecker>,
}

impl Default for ExternalFunctionRegistry {
    fn default() -> Self {
        Self::new(ExternalFunctionsRegistryConfig::default())
    }
}

impl ExternalFunctionRegistry {
    /// Create a new registry
    /// Creates a new instance
    #[must_use]
    pub fn new(config: ExternalFunctionsRegistryConfig) -> Self {
        Self {
            config,
            libraries: HashMap::new(),
            functions: HashMap::new(),
            safety_checker: Arc::new(SafetyChecker::new(SecurityClearance::Public)),
        }
    }

    /// Load a library
    /// Loads library
    /// Loads library
    ///
    /// # Errors
    /// Returns an error if the library loading fails
    pub fn load_library(&mut self, library_path: &str) -> Result<String, BearDogError> {
        let library_id = Uuid::new_v4().to_string();

        // Create library handle
        let library_handle = LibraryHandle {
            id: library_id.clone(),
            name: library_path
                .split('/')
                .next_back()
                .unwrap_or("unknown")
                .to_string(),
            path: library_path.into(),
            metadata: LibraryMetadata {
                version: "1.0.0".to_string(),
                description: format!("Library loaded from {library_path}"),
                author: "Unknown".to_string(),
                license: "Unknown".to_string(),
                exported_functions: vec![],
                dependencies: vec![],
                custom: HashMap::new(),
            },
            status: LibraryStatus::Loaded,
            loaded_at: chrono::Utc::now(),
        };

        self.libraries.insert(library_id.clone(), library_handle);
        Ok(library_id)
    }

    /// Unload a library
    ///
    /// # Errors
    /// Returns an error if the library is not found
    pub fn unload_library(&mut self, library_id: &str) -> Result<(), BearDogError> {
        if self.libraries.remove(library_id).is_some() {
            // Also remove all functions from this library
            self.functions
                .retain(|_, function| function.library_id != library_id);
            Ok(())
        } else {
            Err(BearDogError::not_found(format!(
                "Library not found: {library_id}"
            )))
        }
    }

    /// Gets `library_info`
    /// Gets `library_info`
    ///
    /// # Errors
    /// Returns an error if the library is not found
    pub fn get_library_info(&self, library_id: &str) -> Result<LibraryHandle, BearDogError> {
        self.libraries
            .get(library_id)
            .cloned()
            .ok_or_else(|| BearDogError::not_found(format!("Library not found: {library_id}")))
    }

    /// List all loaded libraries
    ///
    /// # Errors
    /// Returns an error if listing fails
    pub fn list_libraries(&self) -> Result<Vec<LibraryHandle>, BearDogError> {
        Ok(self.libraries.values().cloned().collect())
    }

    /// Register a function
    ///
    /// # Errors
    /// Returns an error if the library is not found or registration fails
    pub fn register_function(
        &mut self,
        library_id: &str,
        function_name: &str,
        signature: FunctionSignature,
        metadata: FunctionMetadata,
    ) -> Result<String, BearDogError> {
        // Verify library exists
        if !self.libraries.contains_key(library_id) {
            return Err(BearDogError::not_found(format!(
                "Library not found: {library_id}"
            )));
        }

        let function_id = Uuid::new_v4().to_string();
        let function_handle = FunctionHandle {
            id: function_id.clone(),
            name: function_name.to_string(),
            library_id: library_id.to_string(),
            signature,
            call_count: 0,
            last_called: None,
            metadata,
        };

        self.functions.insert(function_id.clone(), function_handle);
        Ok(function_id)
    }

    /// Unregister a function
    ///
    /// # Errors
    ///
    /// Returns an error if the function is not found in the registry
    pub fn unregister_function(&mut self, function_id: &str) -> Result<(), BearDogError> {
        if self.functions.remove(function_id).is_some() {
            Ok(())
        } else {
            Err(BearDogError::not_found(format!(
                "Function not found: {function_id}"
            )))
        }
    }

    /// Call a function by ID
    ///
    /// # Errors
    ///
    /// Returns an error if:
    /// - The function is not found
    /// - The function execution fails
    /// - Parameter validation fails
    pub fn call_function(
        &mut self,
        function_id: &str,
        parameters: Vec<FunctionParameter>,
    ) -> Result<FunctionResult, BearDogError> {
        if let Some(function) = self.functions.get_mut(function_id) {
            // Update last called timestamp
            function.last_called = Some(chrono::Utc::now());

            // Convert function handle to external function for safety check
            let external_function = ExternalFunction {
                id: function.id.clone(),
                name: function.name.clone(),
                signature: function.signature.clone(),
                metadata: function.metadata.clone(),
                library_id: function.library_id.clone(),
            };

            // Convert FunctionParameter to ParameterValue for safety check
            let parameter_values: Vec<ParameterValue> = parameters
                .into_iter()
                .map(|param| {
                    let value = param.default_value.clone().unwrap_or(FunctionValue::Null);
                    ParameterValue {
                        value,
                        parameter: param,
                    }
                })
                .collect();

            self.safety_checker
                .check_function_call(&external_function, &parameter_values)?;

            // Log the call if enabled
            if self.config.enable_logging {
                info!(
                    "Calling function: {} with {} parameters",
                    function_id,
                    parameter_values.len()
                );
            }

            // Simulate function call (in real implementation, this would call the actual function)
            let start_time = std::time::Instant::now();
            let result = FunctionResult {
                success: true,
                value: Some(FunctionValue::String(
                    "Function called successfully".to_string(),
                )),
                error: None,
                #[allow(clippy::cast_possible_truncation)]
                execution_time_us: start_time.elapsed().as_micros().min(u128::from(u64::MAX))
                    as u64,
            };
            Ok(result)
        } else {
            Err(BearDogError::not_found(format!(
                "Function not found: {function_id}"
            )))
        }
    }

    /// Gets function information
    ///
    /// # Errors
    ///
    /// Returns an error if the function is not found in the registry
    pub fn get_function_info(&self, function_id: &str) -> Result<FunctionHandle, BearDogError> {
        self.functions
            .get(function_id)
            .cloned()
            .ok_or_else(|| BearDogError::not_found(format!("Function not found: {function_id}")))
    }

    /// Checks if a library path is allowed
    /// Checks if library path allowed
    #[allow(dead_code)]
    fn is_library_path_allowed(&self, path: &str) -> bool {
        let path_buf = std::path::PathBuf::from(path);

        for allowed_dir in &self.config.allowed_directories {
            if path_buf.starts_with(allowed_dir) {
                return true;
            }
        }

        false
    }
}

// Safety checking for external functions

use super::types::{ExternalFunction, FunctionParameter, FunctionValue, SecurityClearance};
use beardog_errors::BearDogError;
use beardog_traits::unified::security::PolicyContext;
use beardog_traits::unified::{PolicyEngine, UnifiedTraitError};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tracing::debug;

#[derive(Debug, Clone)]
pub struct ParameterValue {
    /// Function parameter definition
    /// The parameter value
    pub parameter: FunctionParameter,
    /// The value value
    pub value: FunctionValue,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SafetyPolicy {
    pub policy_id: String,
    /// Patterns of function names this policy applies to
    /// Collection of function patterns
    pub function_patterns: Vec<String>,
    /// Minimum security clearance required
    /// The required clearance value
    pub required_clearance: SecurityClearance,
    /// Whether parameter validation is required
    pub parameter_validation: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SafetyDecision {
    /// Whether allowed is enabled
    pub allowed: bool,
    /// The reason value
    pub reason: String,
    /// Collection of required actions
    pub required_actions: Vec<String>,
}

#[derive(Debug)]
pub struct SafetyChecker {
    security_clearance: SecurityClearance,
    loaded_policies: HashMap<String, SafetyPolicy>,
}

impl SafetyChecker {
    /// Create new safety checker
    /// Creates a new instance
    #[must_use]
    pub fn new(security_clearance: SecurityClearance) -> Self {
        Self {
            security_clearance,
            loaded_policies: HashMap::new(),
        }
    }

    /// Check if function call is safe
    ///
    /// # Errors
    ///
    /// Returns an error if:
    /// - Insufficient security clearance
    /// - Parameter validation fails
    pub fn check_function_call(
        &self,
        function: &ExternalFunction,
        parameters: &[ParameterValue],
    ) -> Result<(), BearDogError> {
        debug!("Checking safety for function: {}", function.name);

        // Check security clearance
        if function.metadata.security.clearance_required > self.security_clearance {
            return Err(BearDogError::security(
                "Insufficient security clearance for function call".to_string(),
            ));
        }

        // Validate parameters
        for param_value in parameters {
            Self::validate_parameter(param_value)?;
        }

        Ok(())
    }

    /// Validate a single parameter
    /// Validates parameter
    fn validate_parameter(param_value: &ParameterValue) -> Result<(), BearDogError> {
        // For now, just basic validation - can be extended
        if matches!(&param_value.value, FunctionValue::Null) && param_value.parameter.required {
            return Err(BearDogError::validation(
                "Required parameter cannot be null",
            ));
        }

        Ok(())
    }
}

impl PolicyEngine for SafetyChecker {
    type Policy = SafetyPolicy;
    type Decision = SafetyDecision;

    async fn evaluate(
        &self,
        policy: &Self::Policy,
        _context: PolicyContext,
    ) -> Result<Self::Decision, UnifiedTraitError> {
        // Basic policy evaluation logic
        let allowed = self.security_clearance >= policy.required_clearance;

        let decision = SafetyDecision {
            allowed,
            reason: if allowed {
                "Security clearance sufficient".to_string()
            } else {
                "Insufficient security clearance".to_string()
            },
            required_actions: if allowed {
                vec![]
            } else {
                vec!["Upgrade security clearance".to_string()]
            },
        };

        Ok(decision)
    }

    /// Loads policy
    async fn load_policy(&mut self, policy: Self::Policy) -> Result<(), UnifiedTraitError> {
        self.loaded_policies
            .insert(policy.policy_id.clone(), policy);
        Ok(())
    }

    async fn list_policies(&self) -> Result<Vec<String>, UnifiedTraitError> {
        Ok(self.loaded_policies.keys().cloned().collect())
    }

    /// Removes policy
    async fn remove_policy(&mut self, policy_id: &str) -> Result<(), UnifiedTraitError> {
        self.loaded_policies.remove(policy_id);
        Ok(())
    }

    /// Validates policy
    async fn validate_policy(&self, policy: &Self::Policy) -> Result<bool, UnifiedTraitError> {
        // Basic policy validation
        Ok(!policy.policy_id.is_empty() && !policy.function_patterns.is_empty())
    }
}

