        })
    }

    /// Start the load balancer background tasks
    ///
    /// # Errors
    ///
    /// Returns error if:
    /// - Background tasks fail to start
    /// - Load balancer is already running
    pub const fn start(&self) -> Result<(), BearDogError> {
