    #[test]
    fn test_genetics_pool() {
        let mut pool = GeneticsPool::new();

        assert!(pool.allocate("test-pool", 1024).is_ok());
        assert_eq!(pool.pool_count(), 1);
        assert_eq!(pool.total_allocated_bytes(), 1024);

