        let first_half: f64 =
            values[0..values.len() / 2].iter().sum::<f64>() / (values.len() / 2) as f64;
        let second_half: f64 = values[values.len() / 2..].iter().sum::<f64>()
            / (values.len() - values.len() / 2) as f64;
        let change_percent = ((second_half - first_half) / first_half) * 100.0;
