        self.operations_count.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

        match algorithm {
            KemAlgorithm::Kyber512 => self.kyber_instance.generate_keypair_512(),
            KemAlgorithm::Kyber768 => self.kyber_instance.generate_keypair_768(),
