        let hash1 = compute_sha256_hash(data1).unwrap();
        let hash2 = compute_sha256_hash(data2).unwrap();

        assert_ne!(hash1, hash2);

        // Verify hashes differ in many bits (avalanche effect)
        let diff_bits: u32 = hash1
            .iter()
