        Self {
            id: id.to_string(),
            name: name.to_string(),
            description: description.to_string(),
            rule_type,
            severity,
            condition,
            enabled: true,
            priority: 50, // Medium priority by default
            tags: Vec::new(),
            created_at: now,
            updated_at: now,
            created_by: "system".to_string(),
            version: "1.0.0".to_string(),
            metadata: HashMap::new(),
            // Additional fields
