/// Severity levels for threats
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
pub enum ThreatSeverity {
    /// Low severity threat
    Low,
    /// Medium severity threat
    Medium,
    /// High severity threat
    High,
    /// Critical severity threat
    Critical,
}

impl ThreatSeverity {
    /// Convert severity to numeric score (0-100)
    #[must_use]
    pub const fn to_score(&self) -> u8 {
        match self {
            Self::Low => 25,
            Self::Medium => 50,
            Self::High => 75,
            Self::Critical => 100,
        }
    }

    #[must_use]
    /// Convert numeric score to severity level
    pub const fn from_score(score: u8) -> Self {
        match score {
            0..=30 => Self::Low,
            31..=60 => Self::Medium,
            61..=85 => Self::High,
            86..=100 => Self::Critical,
            _ => Self::Critical, // Fallback for any edge cases
        }
    }
 #[must_use]

    /// Convert to string representation (compatibility)
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Low => "Low",
            Self::Medium => "Medium",
            Self::High => "High",
            Self::Critical => "Critical",
        }
    }
}

