//! backward compatibility during the migration period.
//!
//! ## Migration Path
//!
//! **DO NOT USE** these traits for new code. Use the following instead:
//!
//! ### Current (Recommended):
//! ```rust
//! use beardog_traits::unified::{
//!     BearDogProvider,
//!     SecurityProvider,
//!     CryptoProvider,
//!     HsmProvider,
//!     MonitoringProvider,
//! };
//! ```
//!
