    fn security_level() -> SecurityLevel {
        SecurityLevel::Software
    }

    fn supported_algorithms() -> &'static [Algorithm] {
        &[Algorithm::EcdsaP256, Algorithm::Aes256Gcm]
    }

    fn hardware_backed() -> bool {
        false
    }
}

