        user_id: Option<String>,
        key_id: Option<String>,
        success: bool,
        error_message: Option<String>,
        details: std::collections::HashMap<String, String>,
    ) -> Result<(), BearDogError> {
        let entry = AuditLogEntry {
            timestamp: chrono::Utc::now(),
            operation,
            user_id,
