/// Pure Rust crypto provider
pub struct RustCryptoProvider;

impl RustCryptoProvider {
    /// Create new Rust crypto provider
    ///
    /// # Errors
    /// Returns an error if the provider cannot be created
    pub async fn new() -> Result<Self, BearDogError> {
