#[async_trait::async_trait]
impl CryptoProvider<KeyType> for RustCryptoProvider {
    async fn initialize(&self) -> Result<(), BearDogError> {
        info!("Initializing Rust crypto provider");
        Ok(())
    }

    async fn generate_key_material(&self, key_type: &KeyType) -> Result<Vec<u8>, BearDogError> {
        debug!("Generating {:?} key with Rust crypto", key_type);
        let key_length = match key_type {
            KeyType::Aes256 => 32,
            KeyType::ChaCha20 => 32,
            KeyType::Ed25519 => 32,
            KeyType::EccP256 => 32,
            KeyType::EccP384 => 48,
            KeyType::Rsa { key_size } => key_size / 8,
            _ => 32,
        };
        let mut key_material = vec![0u8; key_length as usize];
        rand::thread_rng().fill_bytes(&mut key_material);
        debug!("Generated {} byte key", key_material.len());
        Ok(key_material)
    }

    async fn encrypt(&self, key_material: &[u8], plaintext: &[u8]) -> Result<Vec<u8>, BearDogError> {
        debug!("Encrypting {} bytes with ChaCha20-Poly1305", plaintext.len());

        if key_material.len() != 32 {
            return Err(BearDogError::Crypto {
                message: format!(
                    "Invalid key size for ChaCha20-Poly1305: expected 32 bytes, got {}",
                    key_material.len()
                ),
            });
        }

        let key: [u8; 32] = key_material.try_into().map_err(|_| BearDogError::Crypto {
            message: "Invalid key length".to_string(),
        })?;

        let cipher = ChaCha20Poly1305::new(&key.into());
        let nonce = ChaCha20Poly1305::generate_nonce(&mut OsRng);

        let ciphertext = cipher
            .encrypt(&nonce, plaintext)
            .map_err(|e| BearDogError::Crypto {
                message: format!("Encryption failed: {e}"),
            })?;

        let mut result = nonce.to_vec();
        result.extend(ciphertext);
        debug!("Encrypted to {} bytes", result.len());
        Ok(result)
    }

    async fn decrypt(&self, key_material: &[u8], ciphertext: &[u8]) -> Result<Vec<u8>, BearDogError> {
        debug!("Decrypting {} bytes with ChaCha20-Poly1305", ciphertext.len());

        if ciphertext.len() < 12 {
            return Err(BearDogError::Crypto {
                message: format!(
                    "Ciphertext too short: expected at least 12 bytes, got {}",
                    ciphertext.len()
                ),
            });
        }

        let key: [u8; 32] = key_material.try_into().map_err(|_| BearDogError::Crypto {
            message: "Invalid key length".to_string(),
        })?;

        let cipher = ChaCha20Poly1305::new(&key.into());
        let (nonce_bytes, encrypted_data) = ciphertext.split_at(12);
        let nonce = nonce_bytes.try_into().map_err(|_| BearDogError::Crypto {
            message: "Invalid nonce length".to_string(),
        })?;

        let plaintext = cipher
            .decrypt(nonce, encrypted_data)
            .map_err(|e| BearDogError::Crypto {
                message: format!("Decryption failed: {e}"),
            })?;

        debug!("Decrypted to {} bytes", plaintext.len());
        Ok(plaintext)
    }

    async fn sign(&self, key_material: &[u8], data: &[u8]) -> Result<Vec<u8>, BearDogError> {
        debug!("Signing {} bytes with Ed25519", data.len());

        if key_material.len() != 32 {
            return Err(BearDogError::Crypto {
                message: format!(
                    "Invalid key size for Ed25519: expected 32 bytes, got {}",
                    key_material.len()
                ),
            });
        }

        let signing_key = SigningKey::from_bytes(key_material.try_into().map_err(|_| {
            BearDogError::Crypto {
                message: "Invalid signing key".to_string(),
            }
        })?);

        let signature = signing_key.sign(data);
        debug!("Generated signature of {} bytes", signature.to_bytes().len());
        Ok(signature.to_bytes().to_vec())
    }

    async fn verify(
        &self,
        key_material: &[u8],
        data: &[u8],
        signature: &[u8],
    ) -> Result<bool, BearDogError> {
        debug!("Verifying signature for {} bytes with Ed25519", data.len());

        if signature.len() != 64 {
            return Err(BearDogError::Crypto {
                message: format!(
                    "Invalid signature size for Ed25519: expected 64 bytes, got {}",
                    signature.len()
                ),
            });
        }

        let verifying_key = VerifyingKey::from_bytes(key_material.try_into().map_err(|_| {
            BearDogError::Crypto {
                message: "Invalid verifying key".to_string(),
            }
        })?).map_err(|e| BearDogError::Crypto {
            message: format!("Failed to create verifying key: {e}"),
        })?;

        let sig: [u8; 64] = signature.try_into().map_err(|_| BearDogError::Crypto {
            message: "Invalid signature length".to_string(),
        })?;

        match verifying_key.verify(data, &sig.into()) {
            Ok(()) => {
                debug!("Signature valid");
                Ok(true)
            }
            Err(_) => {
                debug!("Signature invalid");
                Ok(false)
            }
        }
    }

    async fn derive_key(
        &self,
        root_key: &[u8],
        derivation_data: &[u8],
    ) -> Result<Vec<u8>, BearDogError> {
        debug!("Deriving key with HKDF-SHA256");

        if root_key.is_empty() {
            return Err(BearDogError::Crypto {
                message: "Root key cannot be empty".to_string(),
            });
        }

        let hkdf = Hkdf::<Sha256>::new(None, root_key);
        let mut derived_key = vec![0u8; 32];
        hkdf.expand(derivation_data, &mut derived_key)
            .map_err(|e| BearDogError::Crypto {
                message: format!("Key derivation failed: {e}"),
            })?;

        debug!("Derived key of {} bytes", derived_key.len());
        Ok(derived_key)
    }
}

