//! HSM Key Types
//!
//! Type definitions for cryptographic keys managed by the HSM.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// Key type enumeration
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum KeyType {
    /// AES encryption key
    Aes { key_size: u32 },
    /// RSA key pair
    Rsa { key_size: u32 },
    /// HMAC key
    Hmac { key_size: u32 },
    /// Key derivation key
    KeyDerivation { key_size: u32 },
    /// Elliptic curve P-256
    EccP256,
    /// Elliptic curve P-384
    EccP384,
    /// Elliptic curve P-521
    EccP521,
    /// Ed25519 signing key
    Ed25519,
    /// X25519 key exchange
    X25519,
    /// Custom key type
    Custom(String),
}

/// Universal key structure
#[derive(Debug, Clone)]
pub struct UniversalKey {
    /// Key ID
    pub id: String,
    /// HSM type
    pub hsm_type: String,
    /// Key type
    pub key_type: KeyType,
    /// Key metadata
    pub metadata: KeyMetadata,
    /// Key material (encrypted or reference)
    pub key_material: KeyMaterial,
    /// HSM tier
    pub hsm_tier: String,
    /// Health status
    pub health_status: KeyHealthStatus,
    /// Optional attestation
    pub attestation: Option<KeyAttestation>,
    /// Creation timestamp
    pub created_at: DateTime<Utc>,
}

/// Type alias for compatibility
pub type HsmKey = UniversalKey;

/// Type alias for HSM key metadata (compatibility)
pub type HsmKeyMetadata = KeyMetadata;

/// Key material variants
#[derive(Debug, Clone)]
pub enum KeyMaterial {
    /// Encrypted key data
    Encrypted {
        /// Encrypted key bytes
        encrypted_data: Vec<u8>,
        /// Encryption algorithm used
        encryption_algorithm: String,
        /// Optional KDF parameters
        kdf_params: Option<HashMap<String, String>>,
    },
    /// Reference to HSM-stored key
    Reference {
        /// Key reference identifier
        key_reference: String,
        /// HSM instance identifier
        hsm_instance: String,
    },
    /// Hardware-backed key reference
    HardwareReference {
        /// Hardware reference
        reference: String,
        /// HSM location/identifier
        hsm_location: String,
    },
    /// Key handle for indirect access
    Handle {
        /// Key handle identifier
        key_handle: String,
        /// Handle type
        handle_type: String,
    },
}

/// HSM key information
#[derive(Debug, Clone)]
pub struct HsmKeyInfo {
    /// Key identifier
    pub key_id: String,
    /// Performance metrics
    pub performance_metrics: KeyPerformanceMetrics,
    /// Last access timestamp
    pub last_accessed: Option<DateTime<Utc>>,
    /// Access count
    pub access_count: u64,
    /// Usage policy
    pub usage_policy: KeyUsagePolicy,
}

/// Key performance metrics
#[derive(Debug, Clone)]
pub struct KeyPerformanceMetrics {
    /// Average latency in milliseconds
    pub avg_latency_ms: f64,
    /// Operations per second
    pub ops_per_second: f64,
    /// Error rate (0.0-1.0)
    pub error_rate: f64,
    /// Total operations performed
    pub total_operations: u64,
}

impl Default for KeyPerformanceMetrics {
    fn default() -> Self {
        Self {
            avg_latency_ms: 0.0,
            ops_per_second: 0.0,
            error_rate: 0.0,
            total_operations: 0,
        }
    }
}

/// Key attestation information
#[derive(Debug, Clone)]
pub struct KeyAttestation {
    /// Certificate chain
    pub certificate_chain: Vec<Vec<u8>>,
    /// Attestation statement
    pub attestation_statement: Vec<u8>,
    /// Attestation format
    pub format: String,
    /// Attestation timestamp
    pub timestamp: DateTime<Utc>,
}

/// Key metadata
#[derive(Debug, Clone)]
pub struct KeyMetadata {
    /// Key identifier
    pub key_id: String,
    /// Key type
    pub key_type: KeyType,
    /// Key alias/name
    pub alias: Option<String>,
    /// Creation timestamp
    pub created_at: DateTime<Utc>,
    /// Expiration timestamp
    pub expires_at: Option<DateTime<Utc>>,
    /// Custom metadata tags
    pub tags: HashMap<String, String>,
}

impl KeyMetadata {
    /// Create new key metadata
    pub fn new(key_id: String, key_type: KeyType) -> Self {
        Self {
            key_id,
            key_type,
            alias: None,
            created_at: Utc::now(),
            expires_at: None,
            tags: HashMap::new(),
        }
    }
}

/// Key health status
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum KeyHealthStatus {
    /// Key is healthy
    Healthy,
    /// Key is degraded
    Degraded,
    /// Key is compromised
    Compromised,
    /// Key is expired
    Expired,
    /// Key is revoked
    Revoked,
}

/// Key usage policy
#[derive(Debug, Clone)]
pub struct KeyUsagePolicy {
    /// Allowed operations
    pub allowed_operations: Vec<KeyOperation>,
    /// Maximum uses (None = unlimited)
    pub max_uses: Option<u64>,
    /// Usage rate limit (operations per second)
    pub rate_limit: Option<f64>,
    /// Require user authentication
    pub require_auth: bool,
}

impl Default for KeyUsagePolicy {
    fn default() -> Self {
        Self {
            allowed_operations: vec![
                KeyOperation::Encrypt,
                KeyOperation::Decrypt,
                KeyOperation::Sign,
                KeyOperation::Verify,
            ],
            max_uses: None,
            rate_limit: None,
            require_auth: false,
        }
    }
}

/// Key operations
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum KeyOperation {
    /// Encryption
    Encrypt,
    /// Decryption
    Decrypt,
    /// Signing
    Sign,
    /// Signature verification
    Verify,
    /// Key wrapping
    Wrap,
    /// Key unwrapping
    Unwrap,
    /// Key derivation
    Derive,
    /// Key export
    Export,
}

