    /// Create new comprehensive status with defaults
    pub fn new() -> Self {
        Self {
            health: HsmHealthStatus {
                is_healthy: true,
                last_check: Utc::now(),
                error_message: None,
                performance_metrics: PerformanceMetrics::default(),
            },
            operational: OperationalStatus {
                is_online: true,
                is_ready: true,
                connection_status: ConnectionStatus::Connected,
                active_operations: 0,
                queued_operations: 0,
            },
            security: SecurityStatus {
                is_secure: true,
                tamper_detected: false,
                last_audit: None,
                failed_auth_attempts: 0,
            },
            resources: ResourceMetrics {
                cpu_percent: 0.0,
                memory_bytes: 0,
                disk_bytes: 0,
                network_bps: 0,
            },
            availability: AvailabilityMetrics {
                uptime_percent: 100.0,
                uptime_seconds: 0,
                downtime_seconds: 0,
                last_downtime: None,
            },
            errors: ErrorStatistics {
                total_errors: 0,
                errors_last_hour: 0,
                errors_last_day: 0,
                error_rate: 0.0,
                last_error: None,
                last_error_time: None,
            },
            status_entries: Vec::new(),
        }
    }

    /// Check if status is overall healthy
    pub fn is_healthy(&self) -> bool {
        self.health.is_healthy
            && self.operational.is_online
            && self.operational.is_ready
            && self.security.is_secure
            && !self.security.tamper_detected
    }

    /// Get current status level
    pub fn get_status_level(&self) -> StatusLevel {
        if !self.is_healthy() {
            StatusLevel::Critical
        } else if self.errors.error_rate > 0.1 {
            StatusLevel::Warning
        } else {
            StatusLevel::Normal
        }
    }

    /// Add status entry
    pub fn add_status_entry(&mut self, entry: StatusEntry) {
        self.status_entries.push(entry);
    }
}

impl Default for ComprehensiveHsmStatus {
    fn default() -> Self {
        Self::new()
    }
}

