    #[test]
    fn test_entropy_collector_creation() {
        let collector = SoftwareEntropyCollector::new();
        assert!(collector.collect_entropy(32).is_ok());
        assert!(collector.get_quality_score() > 0.0);
    }

    #[test]
    fn test_collect_entropy() {
