        let discovered = {
            let d = discovery.lock().await;
            d.get_all_hsms().unwrap_or_default()
        };

        if let Some(hsm) = discovered.first() {
            let hsm_id = hsm.id.clone();
            let disc1 = Arc::clone(&discovery);
            let disc2 = Arc::clone(&discovery);
            let id1 = hsm_id.clone();
