                d.update_hsm_status(&id1, HsmHealthStatus::Healthy)
            });

            let handle2 = tokio::spawn(async move {
                let mut d = disc2.lock().await;
                d.update_hsm_status(&id2, HsmHealthStatus::Degraded)
            });

