        debug!("Scanning for USB device: {} ({:04x}:{:04x})", device_name, vendor_id, product_id);

        Ok(Some(UsbDeviceInfo {
            vendor_id,
            product_id,
            device_name: device_name.to_string(),
        }))
    })
}

