        {
            let mut d = discovery.lock().await;
            let _ = d.discover_all_hsms()?;
        }

        let mut handles = vec![];

        for _ in 0..3 {
            let disc = Arc::clone(&discovery);
            handles.push(tokio::spawn(async move {
                let d = disc.lock().await;
                d.perform_health_checks()
            }));
