}

/// Cache configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CacheConfig {
    /// Enable caching
    pub enabled: bool,
    /// Cache size (number of entries)
    pub size: usize,
    /// Cache TTL
    pub ttl: Duration,
}

/// Thread pool configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ThreadPoolConfig {
    /// Core thread count
    pub core_threads: usize,
    /// Maximum thread count
    pub max_threads: usize,
    /// Thread keep-alive time
    pub keep_alive: Duration,
}

/// Resource limits
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResourceLimits {
    /// Maximum memory usage (MB)
    pub max_memory_mb: Option<u64>,
    /// Maximum CPU usage (percentage)
    pub max_cpu_percent: Option<f64>,
    /// Request timeout
    pub request_timeout: Duration,
}

impl Default for PerformanceDomainConfig {
    fn default() -> Self {
        Self {
            cache: CacheConfig::default(),
            threading: ThreadPoolConfig::default(),
            limits: ResourceLimits::default(),
        }
    }
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            size: 10000,
            ttl: Duration::from_secs(3600),
        }
    }
}

impl Default for ThreadPoolConfig {
    fn default() -> Self {
        let cores = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(4);
        Self {
            core_threads: cores,
            max_threads: cores * 2,
            keep_alive: Duration::from_secs(60),
        }
    }
}

impl Default for ResourceLimits {
    fn default() -> Self {
        Self {
            max_memory_mb: None,
            max_cpu_percent: None,
            request_timeout: Duration::from_secs(30),
        }
    }
}

impl PerformanceDomainConfig {
    /// Load from environment variables
    pub fn from_env() -> Result<Self, BearDogError> {
        let config = Self::default();
        Ok(config)
    }

    /// Validate configuration
    pub fn validate(&self) -> Result<(), BearDogError> {
        if self.threading.core_threads == 0 {
            return Err(BearDogError::validation("Core threads must be greater than 0"));
        }
        Ok(())
    }
}

