#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_universal_hsm_config_creation() {
        let config = UniversalHsmConfig::new();
        assert!(config.enable_discovery);
        assert!(!config.capability_config.required_capabilities.is_empty());
    }

    #[test]
    fn test_high_security_config() {
        let config = UniversalHsmConfig::high_security();
        assert_eq!(
            config
                .capability_config
                .security_requirements
                .min_security_level,
            "critical"
        );
        assert!(
            config
                .capability_config
                .security_requirements
                .require_hardware_backed
        );
        assert!(
            config
                .capability_config
                .performance_requirements
                .max_latency_ms
                <= 50
        );
    }

    #[test]
    fn test_development_config() {
        let config = UniversalHsmConfig::development();
        assert_eq!(
            config
                .capability_config
                .security_requirements
                .min_security_level,
            "basic"
        );
        assert!(
            !config
                .capability_config
                .security_requirements
                .require_hardware_backed
        );
        assert!(
            config
                .capability_config
                .performance_requirements
                .max_latency_ms
                >= 1000
        );
    }

