            tcp_nodelay: true,
        }
    }
}

impl Default for StorageResourceConfig {
    fn default() -> Self {
        Self {
            max_disk_usage_percent: 80.0,
            temp_dir_cleanup_interval: Duration::from_secs(3600), // 1 hour
            log_rotation_size_mb: 100,
            log_retention_days: 30,
        }
    }
}

impl Default for ConnectionConfig {
    fn default() -> Self {
        Self {
            pool_size: 10,
            max_idle_connections: 5,
            connection_lifetime: Duration::from_secs(1800), // 30 minutes
            health_check_interval: Duration::from_secs(60), // 1 minute
        }
    }
}

impl ResourceManagementConfig {
    /// Create a new resource management configuration
    #[must_use]
    /// Creates a new instance
    pub fn new() -> Self {
        Self::default()
    }

    #[must_use]
    pub fn production() -> Self {
        Self {
            memory: MemoryConfig {
                enable_memory_profiling: true,
                gc_tuning: GcTuningConfig {
                    strategy: GcStrategy::Balanced,
                    target_pause_ms: Some(10),
                    throughput_target_percent: Some(95),
                },
                ..Default::default()
            },
            cpu: CpuConfig {
                enable_cpu_profiling: true,
                ..Default::default()
            },
            network: NetworkResourceConfig {
                max_connections: 10000,
                connection_timeout: Duration::from_secs(10),
                ..Default::default()
            },
            storage: StorageResourceConfig {
                max_disk_usage_percent: 70.0,
                temp_dir_cleanup_interval: Duration::from_secs(1800), // 30 minutes
                log_rotation_size_mb: 500,
                log_retention_days: 90,
            },
            connections: ConnectionConfig {
                pool_size: 50,
                max_idle_connections: 25,
                connection_lifetime: Duration::from_secs(3600), // 1 hour
                health_check_interval: Duration::from_secs(30), // 30 seconds
            },
        }
    }

    /// Validate the resource configuration
    /// Validates input
    /// Validates input
    pub fn validate(&self) -> Result<(), BearDogError> {
        // Validate memory settings
        if let (Some(initial), Some(max)) = (
            self.memory.initial_heap_size_mb,
            self.memory.max_heap_size_mb,
        ) {
            if initial > max {
                return Err(BearDogError::Business {
                    message: "Initial heap size cannot be larger than maximum heap size"
                        .to_string(),
                    category: beardog_errors::BusinessErrorCategory::Validation,
                });
            }
        }

        // Validate network settings
        if self.network.max_connections == 0 {
            return Err(BearDogError::Business {
                message: "Maximum connections must be greater than 0".to_string(),
                category: beardog_errors::BusinessErrorCategory::Validation,
            });
        }

        // Validate storage settings
        if self.storage.max_disk_usage_percent <= 0.0 || self.storage.max_disk_usage_percent > 100.0
        {
            return Err(BearDogError::Business {
                message: "Disk usage percentage must be between 0 and 100".to_string(),
                category: beardog_errors::BusinessErrorCategory::Validation,
            });
        }

        // Validate connection settings
        if self.connections.pool_size == 0 {
            return Err(BearDogError::Business {
                message: "Connection pool size must be greater than 0".to_string(),
                category: beardog_errors::BusinessErrorCategory::Validation,
            });
        }

        if self.connections.max_idle_connections > self.connections.pool_size {
            return Err(BearDogError::Business {
                message: "Max idle connections cannot exceed pool size".to_string(),
                category: beardog_errors::BusinessErrorCategory::Validation,
            });
        }

        Ok(())
    }
}

//! Runtime Configuration Management
//!
//! Centralized configuration for network endpoints, ports, and other runtime values
//! that were previously hardcoded. All values can be overridden via environment variables.

use serde::{Deserialize, Serialize};
use std::env;

/// Runtime network configuration with environment variable overrides
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuntimeNetworkConfig {
    /// Discovery endpoint URL
    pub discovery_endpoint: String,
    /// API server host
    pub api_host: String,
    /// API server port
    pub api_port: u16,
    /// Metrics endpoint port
    pub metrics_port: u16,
    /// Health check port
    pub health_port: u16,
    /// WebSocket port
    pub ws_port: u16,
    /// gRPC port
    pub grpc_port: u16,
    /// Connection timeout in seconds
    pub timeout_seconds: u64,
    /// Maximum connections
    pub max_connections: usize,
    /// Enable TLS
    pub enable_tls: bool,
}

impl Default for RuntimeNetworkConfig {
    fn default() -> Self {
        // Default ports - can be overridden via environment variables
        const DEFAULT_API_PORT: u16 = 8080;
        const DEFAULT_METRICS_PORT: u16 = 9090;
        const DEFAULT_HEALTH_PORT: u16 = 8081;
        const DEFAULT_WS_PORT: u16 = 3000;
        const DEFAULT_GRPC_PORT: u16 = 50051;
        const DEFAULT_TIMEOUT_SECONDS: u64 = 30;

        Self {
            discovery_endpoint: env::var("BEARDOG_DISCOVERY_ENDPOINT")
                .unwrap_or_else(|_| format!("http://localhost:{}/discover", DEFAULT_API_PORT)),
            api_host: env::var("BEARDOG_API_HOST").unwrap_or_else(|_| "127.0.0.1".to_string()),
            api_port: env::var("BEARDOG_API_PORT")
                .ok()
                .and_then(|p| p.parse().ok())
                .unwrap_or(DEFAULT_API_PORT),
            metrics_port: env::var("BEARDOG_METRICS_PORT")
                .ok()
                .and_then(|p| p.parse().ok())
                .unwrap_or(DEFAULT_METRICS_PORT),
            health_port: env::var("BEARDOG_HEALTH_PORT")
                .ok()
                .and_then(|p| p.parse().ok())
                .unwrap_or(DEFAULT_HEALTH_PORT),
            ws_port: env::var("BEARDOG_WS_PORT")
                .ok()
                .and_then(|p| p.parse().ok())
                .unwrap_or(DEFAULT_WS_PORT),
            grpc_port: env::var("BEARDOG_GRPC_PORT")
                .ok()
                .and_then(|p| p.parse().ok())
                .unwrap_or(DEFAULT_GRPC_PORT),
            timeout_seconds: env::var("BEARDOG_TIMEOUT_SECONDS")
                .ok()
                .and_then(|t| t.parse().ok())
                .unwrap_or(DEFAULT_TIMEOUT_SECONDS),
            max_connections: env::var("BEARDOG_MAX_CONNECTIONS")
                .ok()
                .and_then(|m| m.parse().ok())
                .unwrap_or(1000),
            enable_tls: env::var("BEARDOG_ENABLE_TLS")
                .ok()
                .and_then(|e| e.parse().ok())
                .unwrap_or(true),
        }
    }
}

impl RuntimeNetworkConfig {
    /// Create configuration from environment variables
    pub fn from_env() -> Self {
        Self::default()
    }

    /// Get full API URL
    pub fn api_url(&self) -> String {
        let protocol = if self.enable_tls { "https" } else { "http" };
        format!("{}://{}:{}", protocol, self.api_host, self.api_port)
    }

    /// Get metrics URL
    pub fn metrics_url(&self) -> String {
        format!("http://{}:{}/metrics", self.api_host, self.metrics_port)
    }

    /// Get health check URL
    pub fn health_url(&self) -> String {
        format!("http://{}:{}/health", self.api_host, self.health_port)
    }

    /// Get WebSocket URL
    pub fn ws_url(&self) -> String {
        let protocol = if self.enable_tls { "wss" } else { "ws" };
        format!("{}://{}:{}", protocol, self.api_host, self.ws_port)
    }

    /// Get gRPC endpoint
    pub fn grpc_endpoint(&self) -> String {
        format!("{}:{}", self.api_host, self.grpc_port)
    }
}

/// Runtime HSM configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuntimeHsmConfig {
    /// PKCS#11 library path
    pub pkcs11_library_path: String,
    /// TPM device path
