        fn default() -> Self {
            Self {
                name: "test".to_string(),
                value: 42,
                nested: NestedConfig {
                    enabled: true,
                    items: vec!["item1".to_string(), "item2".to_string()],
                },
            }
        }
    }

    #[test]
    fn test_config_file_operations() {
        let config = TestConfig::default();
        let temp_file = NamedTempFile::new().unwrap();

        // Test save
        UnifiedConfigUtils::save_to_file(&config, temp_file.path()).unwrap();

        // Test load
        let loaded_config: TestConfig = UnifiedConfigUtils::load_from_file(temp_file.path()).unwrap();
        assert_eq!(config, loaded_config);

        // Test validation
        assert!(UnifiedConfigUtils::validate_config_file(temp_file.path()));
    }

