    fn test_config_merging() {
        let base = TestConfig {
            name: "base".to_string(),
            value: 10,
            nested: NestedConfig {
                enabled: false,
                items: vec!["base_item".to_string()],
            },
        };

        let override_config = TestConfig {
            name: "override".to_string(),
            value: 20,
            nested: NestedConfig {
                enabled: true,
                items: vec!["override_item".to_string()],
            },
        };

        let merged = UnifiedConfigUtils::merge_configs(base, override_config.clone()).unwrap();

        // Override should take precedence
        assert_eq!(merged.name, "override");
        assert_eq!(merged.value, 20);
        assert!(merged.nested.enabled);
    }

