pub struct RelationshipHealth {
    pub overall_health: f64,
    pub sustainability_score: f64,
    pub mutual_satisfaction: f64,
    pub ecosystem_contribution: f64,
    pub growth_potential: f64,
    pub resilience_factor: f64,
}

