impl Default for ProviderCapabilities {
    fn default() -> Self {
        Self {
            key_types: vec![
                "RSA-2048".to_string(),
                "RSA-4096".to_string(),
                "ECDSA-P256".to_string(),
                "ECDSA-P384".to_string(),
