    #[must_use]
    pub fn ring() -> Self {
        Self {
            provider_id: "ring".to_string(),
            provider_type: CryptoProviderType::Ring,
            fips_mode: false,
            parameters: HashMap::new(),
            capabilities: ProviderCapabilities::default(),
        }
    }

    /// Creates a software provider configuration (pure Rust)
    #[must_use]
    pub fn software() -> Self {
        Self::default()
    }
}

