            "name": "test",
            "status": "Healthy",
            "message": null,
            "timestamp": "2025-10-09T00:00:00Z",
            "duration_ms": 50,
            "details": {}
        }"#;
        let check: Result<HealthCheck, _> = serde_json::from_str(json);
        assert!(check.is_ok());
        let check = check.unwrap();
        assert_eq!(check.name, "test");
