    /// Set value in cache with TTL
    /// Sets with_ttl
    /// Sets with_ttl
    pub fn set_with_ttl(
        &mut self,
        key: &str,
        value: &[u8],
        ttl: Option<Duration>,
    ) -> Result<(), BearDogError> {
        // Check if we need to evict entries
        if self.entries.len() >= self.config.max_entries && !self.entries.contains_key(key) {
            self.evict_lru()?;
        }

        let now = Instant::now();
        let entry = L1CacheEntry {
            data: value.to_vec(),
            created_at: now,
            accessed_at: now,
            access_count: 1,
            ttl,
        };

        // Insert or update entry
        if self.entries.insert(key.to_string(), entry).is_none() {
            // New entry
            self.access_order.push_back(key.to_string());
        } else {
            // Updated existing entry - move to back
            self.update_access_order(key);
        }

        self.update_stats();
        Ok(())
    }

    /// Remove entry from cache
    /// Removes item
    /// Removes item
    pub fn remove(&mut self, key: &str) -> Result<bool, BearDogError> {
        let removed = self.entries.remove(key).is_some();
        if removed {
            self.remove_from_access_order(key);
            self.update_stats();
        }
        Ok(removed)
    }

    /// Clear all entries from cache
    pub fn clear(&mut self) -> Result<(), BearDogError> {
        self.entries.clear();
        self.access_order.clear();
        self.stats = L1CacheStats::default();
        Ok(())
    }

    /// Get cache statistics
    /// Gets stats
    /// Gets stats
    pub fn get_stats(&self) -> &L1CacheStats {
        &self.stats
    }

    /// Get hit ratio
    pub fn hit_ratio(&self) -> f64 {
        let total = self.stats.hits + self.stats.misses;
        if total == 0 {
            0.0
        } else {
            self.stats.hits as f64 / total as f64
        }
    }

    /// Check if cache contains key
    pub fn contains_key(&self, key: &str) -> bool {
        self.entries.contains_key(key)
    }

    /// Get number of entries in cache
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Check if cache is empty
    /// Checks if empty
