        B * C + C * 64 // Buffer size + cache overhead
    }

    /// Validates input
    /// Validates input
    pub fn validate(&self) -> Result<(), BearDogError> {
        if self.total_memory_usage() > 100 * 1024 * 1024 {
            // 100MB limit
            return Err(BearDogError::validation(
                "Configuration exceeds memory limit",
