            tracing::error!("Operation failed ({}): {:?}", "Valid buffer", e);
            beardog_errors::BearDogError::internal(
                format_args!("Operation failed ({}): {:?}", "Valid buffer", e).to_string(),
            )
        })?;

        assert_eq!(buffer.capacity(), 64);
        assert_eq!(buffer.len(), 0);
        assert!(buffer.is_empty());

        buffer.push(42).map_err(|e| {
            tracing::error!("Operation failed ({}): {:?}", "Push should succeed", e);
            beardog_errors::BearDogError::internal(
                format_args!("Operation failed ({}): {:?}", "Push should succeed", e).to_string(),
            )
        })?;
        assert_eq!(buffer.len(), 1);
        assert!(!buffer.is_empty());

        let value = buffer.pop().ok_or_else(|| {
            tracing::error!("Operation failed ({})", "Pop should succeed");
            beardog_errors::BearDogError::internal(
                "Operation failed: Pop should succeed".to_string(),
            )
        })?;
        assert_eq!(value, 42);
        assert!(buffer.is_empty());
        Ok(())
    }

    #[test]
    fn test_const_str() {
        assert_eq!(ConstStr::len("hello"), 5);
        assert!(ConstStr::is_empty(""));
        assert!(!ConstStr::is_empty("hello"));
        assert!(ConstStr::eq("hello", "hello"));
        assert!(!ConstStr::eq("hello", "world"));

        let hash1 = ConstStr::hash("test");
        let hash2 = ConstStr::hash("test");
        let hash3 = ConstStr::hash("different");
        assert_eq!(hash1, hash2);
        assert_ne!(hash1, hash3);
    }

    #[test]
    fn test_const_metrics() {
        let throughput = ConstMetrics::theoretical_throughput(8192, 1000, 4);
        assert!(throughput > 0);

        let memory = ConstMetrics::memory_requirements(8192, 10, 512, 64);
        assert_eq!(memory, 8192 * 10 + 512 * 64 + 10 * 64);
    }
}

//! Environment-based configuration utilities
//!
//! This module provides utilities for loading configuration from environment variables
//! with sensible defaults and validation.

use std::env;
use std::net::{IpAddr, SocketAddr};
use std::str::FromStr;
use std::time::Duration;

/// Get an environment variable or return a default value
pub fn get_env_or_default(key: &str, default: &str) -> String {
    env::var(key).unwrap_or_else(|_| default.to_string())
}

/// Get an environment variable as a typed value or return a default
pub fn get_env_as<T>(key: &str, default: T) -> T
where
    T: FromStr,
{
    env::var(key)
        .ok()
        .and_then(|s| s.parse::<T>().ok())
        .unwrap_or(default)
}

/// Get a required environment variable or panic with a helpful message
pub fn get_env_required(key: &str) -> String {
    env::var(key).unwrap_or_else(|_| {
        panic!(
            "Required environment variable {} is not set. \
             Please set it in your .env file or environment. \
             See .env.example for reference.",
            key
        )
    })
}

/// Configuration for network endpoints
#[derive(Debug, Clone)]
pub struct NetworkConfig {
    pub host: String,
    pub port: u16,
}

impl NetworkConfig {
    /// Create from environment variables with prefix
    pub fn from_env(prefix: &str) -> Self {
        let host_key = format!("{}_HOST", prefix);
        let port_key = format!("{}_PORT", prefix);

        Self {
            host: get_env_or_default(&host_key, "127.0.0.1"),
            port: get_env_as(&port_key, 8080),
        }
    }

    /// Get as SocketAddr
    pub fn to_socket_addr(&self) -> Result<SocketAddr, std::net::AddrParseError> {
        let ip: IpAddr = self.host.parse()?;
        Ok(SocketAddr::new(ip, self.port))
    }

    /// Get as URL string
    pub fn to_url(&self, scheme: &str) -> String {
        format!("{}://{}:{}", scheme, self.host, self.port)
    }
}

