pub struct BufferPoolMetrics {
    /// Number of `total_requests`
    pub total_requests: u64,
    /// Number of `cache_hits`
    pub cache_hits: u64,
    /// Number of `cache_misses`
    pub cache_misses: u64,
}

impl Default for BufferPoolMetrics {
