/// Optimized string that uses zero-copy techniques
#[derive(Debug, Clone)]
pub enum OptimizedString {
    /// Shared reference to avoid clones
    Shared(Arc<str>),
    Owned(String),
}

impl OptimizedString {
    /// Get the string as a &str
    /// Returns as str
    #[must_use]
    pub fn as_str(&self) -> &str {
        match self {
            Self::Shared(s) => s,
            Self::Owned(s) => s,
        }
    }

    /// Convert to String (may clone if necessary)
    #[must_use]
    pub fn into_string(self) -> String {
        match self {
            Self::Shared(s) => s.to_string(),
            Self::Owned(s) => s,
        }
    }

    /// Check if this is using zero-copy optimization
    /// Checks if optimized
    /// Checks if optimized
    #[must_use]
    pub const fn is_optimized(&self) -> bool {
        matches!(self, Self::Shared(_))
    }
}

impl fmt::Display for OptimizedString {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Shared(s) => write!(f, "{s}"),
            Self::Owned(s) => write!(f, "{s}"),
        }
    }
}

