            Self::Shared(bytes) => bytes,
            Self::Owned(bytes) => bytes,
        }
    }

    /// Convert to `Vec<u8>` (may clone if necessary)
    /// Converts to vec
    #[must_use]
    pub fn to_vec(&self) -> Vec<u8> {
