            BearDogError::Cryptographic(msg) => PyRuntimeError::new_err({}", msg)),
            BearDogError::Network(msg) => PyRuntimeError::new_err({}", msg)),
            BearDogError::Internal(msg) => PyRuntimeError::new_err({}", msg)),
            _ => PyRuntimeError::new_err({:?}", err)),
        }
    }
}

