    info!("⚡ Testing Concurrent Fault Injection");

    let config = ChaosTestConfig {
        max_concurrent_faults: 5,  // Multiple at once
        ..Default::default()
    };

    let controller = ChaosController::new(config);
    controller.start();

    // Inject multiple faults concurrently
