    info!("  OOM condition triggered: {}", fault_id);

    // System should handle OOM gracefully
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;

    injector.remove_fault(&fault_id)?;

    info!("  ✅ OOM scenario handled");

    Ok(())
}

