    assert_eq!(
        BearDogCrypto::decrypt_aes_gcm(&key, &enc_perms, &nonce2).unwrap(),
        permissions
    );
    assert_eq!(
        BearDogCrypto::decrypt_aes_gcm(&key, &enc_expiry, &nonce3).unwrap(),
        expiry
    );
