    fn extract_expression(&self, code: &str) -> EnhancedMigratorResult<String> {
        let unwrap_regex = Regex::new(r"(.+)\s*\.\s*(?:unwrap|expect)\s*\([^)]*\)")?;
        if let Some(caps) = unwrap_regex.captures(code) {
            Ok(caps[1].trim().to_string())
        } else {
            Ok(code.to_string())
        }
