fn replace_panic_macro(&str, context: &PanicContext) -> String {
    if context.has_beardog_result {
        if let Some(msg) = extract_panic_message(original) {
            format!("return Err(BearDogError::system(\"{}\"))", msg)
        } else {
            "return Err(BearDogError::system(\"Operation failed\"))".to_string()
        }
    } else if context.is_test {
        original.to_string() // Keep panics in tests
    } else {
        format!("eprintln!(\"Error: {}\"); return", extract_panic_message(&str, context: &PanicContext) -> String {
    if context.has_beardog_result {
        "return Err(BearDogError::system(&str, context: &PanicContext) -> String {
    if context.has_beardog_result {
        "return Err(BearDogError::system(\"Unexpected code path reached\"))".to_string()
    } else {
        "eprintln!(\"Warning: Unexpected code path reached\"); return".to_string(&str, context: &PanicContext) -> String {
    if context.has_beardog_result {
        "return Err(BearDogError::system(&str, context: &PanicContext) -> String {
    if context.has_beardog_result {
        ".map_err(|e| BearDogError::system({:?}\", e)))?".to_string({:?}\", e); Default::default(&str, context: &PanicContext) -> String {
    if let Some(msg) = extract_expect_message(original) {
        if context.has_beardog_result {
            format!(".map_err(|e| BearDogError::system({{:?}}\", e)))?", msg)
        } else {
            format!(".unwrap_or_else({{:?}}\", e); Default::default() }})", msg)
        }
    } else {
        replace_unwrap(original, context)
    }
}

fn extract_panic_message(panic_call: &str) -> Option<String> {
    if let Some(start) = panic_call.find('"') {
        if let Some(end) = panic_call.rfind('"') {
            if start < end {
                return Some(panic_call[start + 1..end].to_string());
            }
        }
    }
    None
}

fn extract_expect_message(expect_call: &str) -> Option<String> {
    extract_panic_message(expect_call)
}

