            "#[cfg(test)]",
            "mod tests {",
            "assert!",
            "assert_eq!",
            "assert_ne!",
        ];

        for marker in &test_markers {
            if before_position.rfind(marker).is_some() {

                if let Some(last_fn) = before_position.rfind("fn ") {
                    if let Some(marker_pos) = before_position.rfind(marker) {
